  title "全部任务"
  table Todo
}

fn label(p: Int) -> Text
requires p >= 1
ensures len(result) > 0
{
  match p { 1 => "低", 2 => "中", _ => "高" }
}

example label(1) == "低"
example label(5) == "高"

test "新建任务默认未完成" {
  let t = insert(Todo, {title: "测试"})
  assert(t.done == false)
  assert(t.priority == 1)
}

